24	export async function old_queries_still_work(ctx: AssertionContext): Promise<AssertionResult> {
25	  const pgResult = await ctx.pg.query(
26	    "SELECT id, name, price, category FROM app.products ORDER BY id",
27	  );
28	  const chRows = await queryRows<{ id: number; name: string; price: number; category: string }>(
29	    ctx,
30	    "SELECT id, name, price, category FROM analytics.products ORDER BY id",
31	  );
32	  if (pgResult.rows.length !== chRows.length) {
33	    return {
34	      passed: false,
35	      message: `Row count mismatch: pg=${pgResult.rows.length}, ch=${chRows.length}.`,
36	      details: { pgRows: pgResult.rows.length, chRows: chRows.length },
37	    };
38	  }
39	
40	  for (let i = 0; i < pgResult.rows.length; i++) {
41	    const pg = pgResult.rows[i];
42	    const ch = chRows[i];
43	    if (pg.id !== ch.id || pg.name !== ch.name || pg.category !== ch.category) {
44	      return {
45	        passed: false,
46	        message: `Row ${i} mismatch.`,
47	        details: { index: i, pg, ch },
48	      };
49	    }
50	    if (Math.abs(Number(pg.price) - ch.price) > 0.01) {
51	      return {
52	        passed: false,
53	        message: `Row ${i} price mismatch.`,
54	        details: { index: i, pgPrice: pg.price, chPrice: ch.price },
55	      };
56	    }
57	  }
58	  return { passed: true, message: "Old queries still work.", details: { rowCount: pgResult.rows.length } };
59	}
